def search_spend(requests, mode, price_in, price_out, per_source, max_results=5):
    tokens = 0.0
    sources = 0
    unanswerable = 0
    for req in requests:
        tokens += req["in"] * price_in + req["out"] * price_out
        if mode == "on":
            searched = True
        elif mode == "auto":
            searched = bool(req["needs_search"])
        else:
            searched = False
        if searched:
            sources += min(req["sources_available"], max_results)
        elif req["needs_search"]:
            unanswerable += 1
    return {
        "usd": tokens / 1e6 + sources * per_source,
        "sources_used": sources,
        "unanswerable": unanswerable,
    }
